<?php
namespace App\Http\Controllers; use App\Models\{Evaluation,Feedback,User};use App\Notifications\AfhmNotification;use Illuminate\Http\Request;
class SupervisionController extends Controller { public function teachers(Request $r){$teachers=$r->user()->supervisedTeachers()->withCount('teachingReports')->paginate(15);return view('supervision.teachers',compact('teachers'));} public function teacher(Request $r,User $teacher){$this->assigned($r,$teacher);$teacher->load(['teachingReports'=>fn($q)=>$q->latest(),'evaluationsReceived'=>fn($q)=>$q->latest(),'feedbackReceived'=>fn($q)=>$q->latest()]);return view('supervision.teacher',compact('teacher'));} public function feedbackForm(Request $r,User $teacher){$this->assigned($r,$teacher);return view('supervision.feedback',compact('teacher'));} public function feedback(Request $r,User $teacher){$this->assigned($r,$teacher);$d=$r->validate(['rating'=>'required|integer|between:1,5','content'=>'required|string|max:5000']);$d+=['teacher_id'=>$teacher->id,'supervisor_id'=>$r->user()->id,'submitted_at'=>now()];Feedback::create($d);$teacher->notify(new AfhmNotification('You received new feedback from your supervisor.'));return redirect()->route('supervisor.teachers.show',$teacher)->with('success','Feedback submitted successfully.');} public function evaluationForm(Request $r,User $teacher){$this->assigned($r,$teacher);$teacher->load(['teachingReports'=>fn($q)=>$q->latest()->limit(5),'evaluationsReceived'=>fn($q)=>$q->latest()->limit(5)]);return view('supervision.evaluation',compact('teacher'));} public function evaluation(Request $r,User $teacher){$this->assigned($r,$teacher);$d=$r->validate(['score'=>'required|numeric|between:1,5','comments'=>'required|string|max:5000']);$d+=['teacher_id'=>$teacher->id,'supervisor_id'=>$r->user()->id,'evaluated_at'=>now()];Evaluation::create($d);$teacher->notify(new AfhmNotification('A new evaluation is available.'));return redirect()->route('supervisor.teachers.show',$teacher)->with('success','Evaluation submitted successfully.');} private function assigned(Request $r,User $teacher){abort_unless($teacher->role==='teacher'&&$teacher->supervisor_id===$r->user()->id,403);}}
